mapper.select:
SELECT e.id, e.number, e.name, e.gender, e.age,
       d.id AS d_id, d.name AS d_name, d.number AS d_number
FROM employee e
LEFT JOIN department d ON e.dep_id = d.id


        AND e.number = #{number}


        AND e.name LIKE CONCAT('%', #{name}, '%')


        AND e.gender = #{gender}


        AND e.age = #{age}
